// ── Fixture path resolution ─────────────────────────────────────────────────

const FIXTURE_DIR = path.resolve(__dirname, '../../../../ankurah-ts-support/proto/test_fixtures');

function loadFixture(name: string): Uint8Array {
  const filePath = path.join(FIXTURE_DIR, name);
  if (!existsSync(filePath)) {
    throw new Error(
      `Fixture file not found at ${filePath}. ` +
      `Ensure the ankurah-ts-support worktree exists at ../ankurah-ts-support ` +
      `with the ts-port-support branch checked out.`
    );
  }
  const buf = readFileSync(filePath);
  return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
}

// ── Deterministic value constructors (mirrors Rust helpers) ──────────────────

function makeEntityId(seed: number): EntityId {
  const bytes = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    bytes[i] = (seed + i) & 0xff;
  }
  return EntityId.fromBytes(bytes);
}

function makeEventId(seed: number): EventId {
  const bytes = new Uint8Array(32);
  for (let i = 0; i < 32; i++) {
    bytes[i] = (seed + i) & 0xff;
  }
  return EventId.fromBytes(bytes);
}

/**
 * Construct a ULID-based ID from a seed, matching the Rust pattern:
 *   format!("0000000000000000000000{:04}", seed)
 * which produces a 26-char Crockford Base32 string with the seed as decimal digits.
 * e.g. seed=0x10 (16) -> "00000000000000000000000016"
 *      seed=0x30 (48) -> "00000000000000000000000048"
 */
function makeUlidBytes(seed: number): Uint8Array {
  // Rust format!("{:04}", seed) uses decimal formatting
  const seedStr = seed.toString(10).padStart(4, '0');
  const ulidStr = '0000000000000000000000' + seedStr;
  return ulidStringToBytes(ulidStr);
}

function makeTransactionId(seed: number): TransactionId {
  return TransactionId.fromBytes(makeUlidBytes(seed));
}

function makeRequestId(seed: number): RequestId {
  return RequestId.fromBytes(makeUlidBytes(seed));
}

function makeUpdateId(seed: number): UpdateId {
  return UpdateId.fromBytes(makeUlidBytes(seed));
}

function makeQueryId(id: number): QueryId {
  return QueryId.test(BigInt(id));
}

function makeCollectionId(name: string): CollectionId {
  return CollectionId.from(name);
}

function makeClockEmpty(): Clock {
  return Clock.new([]);
}

function makeClockSingle(): Clock {
  return Clock.new([makeEventId(0x10)]);
}

function makeClockMulti(): Clock {
  return Clock.new([
    makeEventId(0x10),
    makeEventId(0x30),
    makeEventId(0x50),
  ]);
}

function makeOperation(diff: number[]): Operation {
  return new Operation(new Uint8Array(diff));
}

function makeOperationSet(): OperationSet {
  const map = new Map<string, Operation[]>();
  map.set('backend_a', [
    makeOperation([0xAA, 0xBB]),
    makeOperation([0xCC]),
  ]);
  map.set('backend_b', [
    makeOperation([0xDD, 0xEE, 0xFF]),
  ]);
  return new OperationSet(map);
}

function makeStateBuffers(): StateBuffers {
  const map = new Map<string, Uint8Array>();
  map.set('buf_alpha', new Uint8Array([0x01, 0x02, 0x03]));
  map.set('buf_beta', new Uint8Array([0x04, 0x05]));
  return new StateBuffers(map);
}

function makeState(): State {
  return new State(makeStateBuffers(), makeClockSingle());
}

function makeAttestation(bytes: number[]): Attestation {
  return new Attestation(new Uint8Array(bytes));
}

function makeAttestationSetEmpty(): AttestationSet {
  return new AttestationSet([]);
}

function makeAttestationSetTwo(): AttestationSet {
  return new AttestationSet([
    makeAttestation([0x42, 0x43]),
    makeAttestation([0x44, 0x45, 0x46]),
  ]);
}

function makeStateFragment(): StateFragment {
  return new StateFragment(makeState(), makeAttestationSetTwo());
}

function makeEventFragment(): EventFragment {
  return new EventFragment(
    makeOperationSet(),
    makeClockSingle(),
    makeAttestationSetEmpty(),
  );
}

function makeEntityState(): EntityState {
  return new EntityState(
    makeEntityId(0x00),
    makeCollectionId('test_collection'),
    makeState(),
  );
}

function makeEvent(): Event {
  return new Event(
    makeCollectionId('test_collection'),
    makeEntityId(0x00),
    makeOperationSet(),
    makeClockSingle(),
  );
}

function makeKnownEntity(): KnownEntity {
  return new KnownEntity(makeEntityId(0x20), makeClockSingle());
}

function makeCausalAssertionFragment(): CausalAssertionFragment {
  return new CausalAssertionFragment(
    { type: 'Equal' },
    makeAttestationSetTwo(),
  );
}

/**
 * Encode a Selection { predicate: name = 'test', order_by: None, limit: None }
 * in bincode format, matching the Rust make_selection() helper.
 *
 * Layout:
 *   Predicate::Comparison (variant 0)
 *     left: Expr::Path (variant 1)
 *       PathExpr { steps: ["name"] }
 *     operator: ComparisonOperator::Equal (variant 0)
 *     right: Expr::Literal (variant 0)
 *       Literal::String (variant 5) "test"
 *   order_by: None (0u8)
 *   limit: None (0u8)
 */
function encodeSelection(writer: BincodeWriter): void {
  // Predicate::Comparison = variant 0
  writer.writeVariant(0);
  // left: Expr::Path = variant 1
  writer.writeVariant(1);
  // PathExpr { steps: Vec<String> }
  writer.writeLength(1); // vec len = 1
  writer.writeString('name'); // steps[0]
  // operator: ComparisonOperator::Equal = variant 0
  writer.writeVariant(0);
  // right: Expr::Literal = variant 0
  writer.writeVariant(0);
  // Literal::String = variant 5
  writer.writeVariant(5);
  writer.writeString('test');
  // order_by: Option::None
  writer.writeU8(0);
  // limit: Option::None
  writer.writeU8(0);
}

/**
 * Read past a Selection in the reader (skip the known bytes).
 * Returns the raw bytes consumed for verification.
 */
function skipSelection(reader: BincodeReader): void {
  // Predicate variant
  const predVariant = reader.readVariant();
  expect(predVariant).toBe(0); // Comparison
  // left: Expr variant
  const leftVariant = reader.readVariant();
  expect(leftVariant).toBe(1); // Path
  // PathExpr steps
  const stepsLen = reader.readLength();
  expect(stepsLen).toBe(1);
  const step0 = reader.readString();
  expect(step0).toBe('name');
  // operator
  const opVariant = reader.readVariant();
  expect(opVariant).toBe(0); // Equal
  // right: Expr variant
  const rightVariant = reader.readVariant();
  expect(rightVariant).toBe(0); // Literal
  // Literal::String variant
  const litVariant = reader.readVariant();
  expect(litVariant).toBe(5); // String
  const litStr = reader.readString();
  expect(litStr).toBe('test');
  // order_by: None
  const orderBy = reader.readU8();
  expect(orderBy).toBe(0);
  // limit: None
  const limit = reader.readU8();
  expect(limit).toBe(0);
}

// ── Helper: compare encoded bytes to fixture ─────────────────────────────────

function expectBytesEqual(actual: Uint8Array, expected: Uint8Array, label: string): void {
  if (actual.length !== expected.length) {
    // Find first difference for debugging
    const minLen = Math.min(actual.length, expected.length);
    for (let i = 0; i < minLen; i++) {
      if (actual[i] !== expected[i]) {
        throw new Error(
          `${label}: length mismatch (actual ${actual.length} vs expected ${expected.length}), ` +
          `first difference at byte ${i}: actual 0x${actual[i].toString(16).padStart(2, '0')} ` +
          `vs expected 0x${expected[i].toString(16).padStart(2, '0')}`
        );
      }
    }
    throw new Error(`${label}: length mismatch (actual ${actual.length} vs expected ${expected.length})`);
  }
  for (let i = 0; i < actual.length; i++) {
    if (actual[i] !== expected[i]) {
      throw new Error(
        `${label}: mismatch at byte ${i}: actual 0x${actual[i].toString(16).padStart(2, '0')} ` +
        `vs expected 0x${expected[i].toString(16).padStart(2, '0')}`
      );
    }
  }
}

